from __future__ import annotations

from typing import Any

from settings_source import SettingsSource


def _simulate_call(duration_ms: int, timeout_ms: int) -> dict[str, Any]:
    if duration_ms > timeout_ms:
        return {"ok": False, "reason": "timeout"}
    return {"ok": True, "reason": "completed"}


def run_job(payload: dict[str, Any], settings: SettingsSource) -> dict[str, Any]:
    job_id = str(payload.get("job_id", "")).strip()
    duration_ms = int(payload.get("duration_ms", 0))
    if not job_id:
        return {"ok": False, "reason": "invalid_job_id", "attempts": 0}
    if duration_ms < 0:
        return {"ok": False, "reason": "invalid_duration", "attempts": 0}

    timeout_ms = settings.get_int("request_timeout_ms", 1200)
    max_retries = settings.get_int("max_retries", 2)
    backoff_ms = settings.get_int("backoff_ms", 100)
    attempts = 0

    while attempts <= max_retries:
        attempts += 1
        call = _simulate_call(duration_ms, timeout_ms)
        if call["ok"]:
            return {
                "ok": True,
                "reason": "job_completed",
                "attempts": attempts,
                "timeout_ms": timeout_ms,
                "backoff_ms": backoff_ms,
            }
    return {
        "ok": False,
        "reason": "job_failed_after_retries",
        "attempts": attempts,
        "timeout_ms": timeout_ms,
        "backoff_ms": backoff_ms,
    }


def run_batch(payloads: list[dict[str, Any]], settings: SettingsSource) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    success = 0
    failed = 0
    for payload in payloads:
        result = run_job(payload, settings)
        results.append(result)
        if result.get("ok"):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed, "results": results}


def summarize_attempts(results: list[dict[str, Any]]) -> int:
    total = 0
    for item in results:
        total += int(item.get("attempts", 0))
    return total


def summarize_failures(results: list[dict[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for item in results:
        if item.get("ok"):
            continue
        reason = str(item.get("reason", "unknown"))
        counts[reason] = counts.get(reason, 0) + 1
    return counts


def estimate_total_backoff(results: list[dict[str, Any]]) -> int:
    total = 0
    for item in results:
        attempts = int(item.get("attempts", 0))
        backoff_ms = int(item.get("backoff_ms", 0))
        if attempts > 1 and backoff_ms > 0:
            total += (attempts - 1) * backoff_ms
    return total

