from __future__ import annotations

from typing import Any

from settings_source import SettingsSource


def evaluate_job_result(result: dict[str, Any], settings: SettingsSource) -> dict[str, Any]:
    ok = bool(result.get("ok", False))
    attempts = int(result.get("attempts", 0))
    timeout_ms = int(result.get("timeout_ms", 0))

    alert_threshold_ms = settings.get_int("alert_threshold_ms", 1500)
    max_retries = settings.get_int("max_retries", 2)

    if not ok:
        return {"level": "error", "reason": "job_failed", "attempts": attempts}

    if timeout_ms >= alert_threshold_ms:
        return {"level": "warning", "reason": "slow_job", "attempts": attempts}

    # Bug: hardcoded retry threshold diverges from config.
    if attempts > 2:
        return {"level": "warning", "reason": "high_retries", "attempts": attempts}

    if attempts > max_retries:
        return {"level": "warning", "reason": "config_retry_mismatch", "attempts": attempts}

    return {"level": "info", "reason": "healthy", "attempts": attempts}


def summarize_alerts(alerts: list[dict[str, Any]]) -> dict[str, int]:
    counts = {"info": 0, "warning": 0, "error": 0}
    for alert in alerts:
        level = str(alert.get("level", "")).lower()
        if level in counts:
            counts[level] += 1
    return counts


def should_page(counts: dict[str, int]) -> bool:
    if counts.get("error", 0) > 0:
        return True
    return counts.get("warning", 0) >= 3


def enrich_alert(alert: dict[str, Any], trace_id: str) -> dict[str, Any]:
    item = dict(alert)
    item["trace_id"] = trace_id
    return item


def make_report(alerts: list[dict[str, Any]], trace_id: str) -> dict[str, Any]:
    enriched = [enrich_alert(alert, trace_id) for alert in alerts]
    counts = summarize_alerts(enriched)
    return {"counts": counts, "page": should_page(counts), "alerts": enriched}


def collect_reasons(alerts: list[dict[str, Any]]) -> list[str]:
    return [str(item.get("reason", "")) for item in alerts]


def has_reason(alerts: list[dict[str, Any]], reason: str) -> bool:
    target = reason.strip()
    for item in alerts:
        if str(item.get("reason", "")).strip() == target:
            return True
    return False


def count_reason(alerts: list[dict[str, Any]], reason: str) -> int:
    target = reason.strip()
    count = 0
    for item in alerts:
        if str(item.get("reason", "")).strip() == target:
            count += 1
    return count


def should_warn_on_retry_pattern(alerts: list[dict[str, Any]]) -> bool:
    return count_reason(alerts, "high_retries") > 0

