from __future__ import annotations

from typing import Any


DEFAULT_SETTINGS = {
    "request_timeout_ms": 1200,
    "max_retries": 2,
    "alert_threshold_ms": 1500,
    "batch_size": 50,
    "backoff_ms": 100,
}


class SettingsSource:
    def __init__(self) -> None:
        self._values: dict[str, Any] = dict(DEFAULT_SETTINGS)

    def load(self) -> dict[str, Any]:
        return dict(self._values)

    def update(self, values: dict[str, Any]) -> None:
        for key, value in values.items():
            self._values[str(key)] = value

    def get_int(self, key: str, fallback: int) -> int:
        raw = self._values.get(key, fallback)
        if isinstance(raw, bool):
            return fallback
        try:
            return int(raw)
        except Exception:
            return fallback

    def reset(self) -> None:
        self._values = dict(DEFAULT_SETTINGS)

    def keys(self) -> list[str]:
        return sorted(self._values.keys())

    def snapshot(self) -> dict[str, Any]:
        return dict(self._values)

    def has_key(self, key: str) -> bool:
        return key in self._values

    def remove(self, key: str) -> bool:
        if key in self._values:
            del self._values[key]
            return True
        return False

    def set_default_if_missing(self, key: str, value: Any) -> None:
        if key not in self._values:
            self._values[key] = value

    def validate_required(self, required: list[str]) -> list[str]:
        missing: list[str] = []
        for key in required:
            if key not in self._values:
                missing.append(key)
        return missing

    def coerce_all_ints(self, keys: list[str], fallback: int = 0) -> dict[str, int]:
        out: dict[str, int] = {}
        for key in keys:
            out[key] = self.get_int(key, fallback)
        return out

    def export_runtime(self) -> dict[str, int]:
        keys = [
            "request_timeout_ms",
            "max_retries",
            "alert_threshold_ms",
            "batch_size",
            "backoff_ms",
        ]
        return self.coerce_all_ints(keys, fallback=0)

    def merge_defaults(self, defaults: dict[str, Any]) -> None:
        for key, value in defaults.items():
            self.set_default_if_missing(str(key), value)

