from __future__ import annotations

from typing import Any

from job_runner import run_job
from monitoring import evaluate_job_result, make_report
from settings_source import SettingsSource


def execute_workflow(payload: dict[str, Any], settings: SettingsSource) -> dict[str, Any]:
    trace_id = str(payload.get("trace_id", "")).strip() or "trace-missing"
    jobs = payload.get("jobs", [])
    if not isinstance(jobs, list):
        return {"ok": False, "reason": "invalid_jobs", "trace_id": trace_id}

    results: list[dict[str, Any]] = []
    alerts: list[dict[str, Any]] = []
    success = 0
    failed = 0

    for job_payload in jobs:
        result = run_job(dict(job_payload), settings)
        results.append(result)
        alert = evaluate_job_result(result, settings)
        alerts.append(alert)
        if result.get("ok"):
            success += 1
        else:
            failed += 1

    report = make_report(alerts, trace_id)
    return {
        "ok": failed == 0,
        "reason": "workflow_completed",
        "trace_id": trace_id,
        "summary": {"success": success, "failed": failed},
        "results": results,
        "alerts": report,
    }


def execute_many(payloads: list[dict[str, Any]], settings: SettingsSource) -> dict[str, Any]:
    outputs: list[dict[str, Any]] = []
    success = 0
    failed = 0
    for payload in payloads:
        output = execute_workflow(payload, settings)
        outputs.append(output)
        if output.get("ok"):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed, "outputs": outputs}


def summarize(outputs: list[dict[str, Any]]) -> dict[str, int]:
    job_success = 0
    job_failed = 0
    for output in outputs:
        summary = output.get("summary", {})
        job_success += int(summary.get("success", 0))
        job_failed += int(summary.get("failed", 0))
    return {"job_success": job_success, "job_failed": job_failed}


def collect_alert_levels(outputs: list[dict[str, Any]]) -> list[str]:
    levels: list[str] = []
    for output in outputs:
        alerts_wrapper = output.get("alerts", {})
        alerts = alerts_wrapper.get("alerts", [])
        if isinstance(alerts, list):
            for alert in alerts:
                levels.append(str(alert.get("level", "")))
    return levels


def any_paged(outputs: list[dict[str, Any]]) -> bool:
    for output in outputs:
        alerts = output.get("alerts", {})
        if bool(alerts.get("page", False)):
            return True
    return False

